  }

  const smsBody = readString(body.body) || readString(body.smsBody);
  if (!smsBody) {
    return json({ ok: false, error: 'Missing "body" for SMS message' }, 400);
  }

  const result = await sendSMS(to, smsBody, { from: body.from });
