import base64, json, urllib.request, ssl

with open('qa/evidence/ivx-conversational-voice-self-upgrade-cert.json', 'rb') as f:
    raw = f.read()

content = base64.b64encode(raw).decode('ascii')
payload = json.dumps({
    'message': 'cert: IVX conversational voice + daily self-upgrade — 4 QA tests passed, self-upgrade success, conversational call placed, all endpoints live',
    'content': content,
    'branch': 'main'
}).encode('utf-8')

req = urllib.request.Request(
    'https://api.github.com/repos/ibb142/ivx-holdings-platform/contents/qa/evidence/ivx-conversational-voice-self-upgrade-cert.json',
    data=payload,
    method='PUT',
    headers={
        'Authorization': 'token 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',
        'Content-Type': 'application/json',
    }
)

ctx = ssl.create_default_context()
try:
    with urllib.request.urlopen(req, context=ctx) as resp:
        body = json.loads(resp.read().decode('utf-8'))
        if 'commit' in body:
            print(f"Evidence pushed: {body['commit']['sha'][:12]}")
            print(f"URL: {body['commit']['html_url']}")
except urllib.error.HTTPError as e:
    body = json.loads(e.read().decode('utf-8'))
    print(f"HTTP {e.code}: {body.get('message','')[:200]}")
except Exception as e:
    print(f"Error: {e}")
PYEOF

